DROP TABLE IF EXISTS ra_games;

CREATE TABLE ra_games (
  id        INTEGER NOT NULL,
  console   TEXT    NOT NULL,
  title     TEXT    NOT NULL,
  md5       TEXT    NOT NULL,
  rom_name  TEXT,
  labels    TEXT,
  patch_url TEXT,
  region    TEXT,
  rom_file  TEXT,
  rom_size  INTEGER,
  PRIMARY KEY (id, console)
);

CREATE INDEX IF NOT EXISTS idx_ra_games_md5     ON ra_games (md5);
CREATE INDEX IF NOT EXISTS idx_ra_games_console ON ra_games (console);





